PREFIX wm: <https://wealth.example.org/ontology/>
PREFIX kg: <https://wealth.example.org/kg/>
PREFIX wmmeta: <https://wealth.example.org/metadata/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX schema1: <http://schema.org/>
PREFIX rdf: <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX xsd: <http://www.w3.org/2001/XMLSchema#>

SELECT ?investorId
       (SUM(xsd:decimal(?cfAmount)) AS ?totalCashFlow)
       (SUM(xsd:decimal(?raAmount)) AS ?totalRebalancingAmount)
       (AVG(xsd:decimal(?newAllocPct)) AS ?avgScenarioNewAllocationPct)
       (xsd:decimal(?riskScore) AS ?riskScore)
       (xsd:decimal(?goalMatchPct) AS ?goalMatchPct)
WHERE {
  # Cash Flow aggregation
  OPTIONAL {
    ?cf a wm:CashFlow ;
        wm:investorId ?investorId ;
        wm:amount ?cfAmount .
  }
  # Rebalancing Action aggregation
  OPTIONAL {
    ?ra a wm:RebalancingAction ;
        wm:investorId ?investorId ;
        wm:amount ?raAmount .
  }
  # Scenario Rebalancing aggregation
  OPTIONAL {
    ?sr a wm:ScenarioRebalancing ;
        wm:investorId ?investorId ;
        wm:newAllocationPct ?newAllocPct .
  }
  # Portfolio Health (risk score & goal match)
  OPTIONAL {
    ?ph a wm:PortfolioHealth ;
        wm:investorId ?investorId ;
        wm:riskScore ?riskScore ;
        wm:goalMatchPct ?goalMatchPct .
  }
}
GROUP BY ?investorId ?riskScore ?goalMatchPct

